        if self.message:
            sys.stderr.write(f"  error: {self.message}\n")
        if self.reason:
            sys.stderr.write(f" reason: {self.reason}\n")
        if self.help_msg:
            sys.stderr.write(f" = help: {self.help_msg}\n")
        sys.exit(self.code)

def parse_args(args, binary_path=None):
    if binary_path is None:
        binary_path = sys.argv[0]

    opts = {
        'version': False,
        'help': False,
        'internal_help': False,
        'headless': False,
        'no_syslog': False,
        'quiet': False,
        'prepend_ts': False,
        'recursive': False,
        'rotated': False,
        'warnings': False,
        'update_formats': False,
        'check_config': False,
        'management': False,
