        'install_file': None,
        'config_dir': None,
        'debug_file': None,
        'since': None,
        'until': None,
        'commands': [],
        'command_files': [],
        'exec_shells': [],
        'files': []
    }

    i = 0
    n = len(args)
    while i < n:
        arg = args[i]

        if arg == '-V' or arg == '--version':
            opts['version'] = True
            i += 1
        elif arg == '-h' or arg == '--help':
