            i += 1
        elif arg == '-n':
            opts['headless'] = True
            i += 1
        elif arg == '-N':
            opts['no_syslog'] = True
            i += 1
        elif arg == '-q':
            opts['quiet'] = True
            i += 1
        elif arg == '-t':
            opts['prepend_ts'] = True
            i += 1
        elif arg == '-r':
            opts['recursive'] = True
            i += 1
        elif arg == '-R':
            opts['rotated'] = True
            i += 1
        elif arg == '-W':
            opts['warnings'] = True
            i += 1
        elif arg == '-u':
            opts['update_formats'] = True
            i += 1
        elif arg == '-C':
            opts['check_config'] = True
            i += 1
        elif arg == '-m':
            opts['management'] = True
            i += 1
            # Collect any subsequent arguments for management mode
            while i < n and not args[i].startswith('-'):
                opts['management_subargs'].append(args[i])
                i += 1
        elif arg == '-i':
            opts['install'] = True
            if i + 1 < n and not args[i+1].startswith('-'):
                opts['install_file'] = args[i+1]
                i += 2
            else:
                raise CLIError("invalid command-line arguments", "-i requires file", code=107)
        elif arg.startswith('-I'):
            val = arg[2:]
            if not val:
                if i + 1 < n:
                    val = args[i+1]
                    i += 2
                else:
                    raise CLIError("invalid command-line arguments", "-I: 1 required TEXT:DIR missing", code=114)
            else:
                i += 1
            if os.path.isfile(val):
                raise CLIError("invalid command-line arguments", f"-I: Directory is actually a file: {val}", code=105)
            if not os.path.exists(val):
                raise CLIError("invalid command-line arguments", f"-I: Directory does not exist: {val}", code=105)
            opts['config_dir'] = val
        elif arg.startswith('-d'):
            val = arg[2:]
            if not val:
                if i + 1 < n:
                    val = args[i+1]
                    i += 2
                else:
                    raise CLIError("invalid command-line arguments", "-d: 1 required FILE missing", code=114)
            else:
                i += 1
            opts['debug_file'] = val
        elif arg.startswith('-S') or arg.startswith('--since'):
            if arg == '-S' or arg == '--since':
                if i + 1 < n:
                    val = args[i+1]
                    i += 2
                else:
                    flag_name = "--since" if arg == '--since' else "-S"
                    raise CLIError("invalid command-line arguments", f"{flag_name}: 1 required TEXT missing", code=114)
            elif arg.startswith('--since='):
                val = arg[8:]
