        elif arg.startswith('-U') or arg.startswith('--until'):
            if arg == '-U' or arg == '--until':
                if i + 1 < n:
                    val = args[i+1]
                    i += 2
                else:
                    flag_name = "--until" if arg == '--until' else "-U"
                    raise CLIError("invalid command-line arguments", f"{flag_name}: 1 required TEXT missing", code=114)
            elif arg.startswith('--until='):
                val = arg[8:]
                i += 1
            elif arg.startswith('-U'):
                val = arg[2:]
                i += 1
            opts['until'] = val
        elif arg.startswith('-c'):
            val = arg[2:]
            if not val:
                if i + 1 < n:
                    val = args[i+1]
                    i += 2
                else:
                    raise CLIError("invalid command-line arguments", "-c: 1 required  missing", code=114)
            else:
                i += 1
            opts['commands'].append(val)
        elif arg.startswith('-f'):
            val = arg[2:]
            if not val:
                if i + 1 < n:
                    val = args[i+1]
                    i += 2
                else:
                    raise CLIError("invalid command-line arguments", "-f: 1 required  missing", code=114)
            else:
                i += 1
            opts['command_files'].append(val)
        elif arg.startswith('-e'):
            val = arg[2:]
            if not val:
                if i + 1 < n:
                    val = args[i+1]
                    i += 2
                else:
                    raise CLIError("invalid command-line arguments", "-e: 1 required  missing", code=114)
            else:
                i += 1
            opts['exec_shells'].append(val)
        elif arg.startswith('-') and len(arg) > 1 and not arg.startswith('--'):
            # Combined short flags like -nN
            valid_chars = True
            flags = arg[1:]
            j = 0
