                c = flags[j]
                if c == 'n': opts['headless'] = True
                elif c == 'N': opts['no_syslog'] = True
                elif c == 'q': opts['quiet'] = True
                elif c == 't': opts['prepend_ts'] = True
                elif c == 'r': opts['recursive'] = True
                elif c == 'R': opts['rotated'] = True
                elif c == 'W': opts['warnings'] = True
                elif c == 'u': opts['update_formats'] = True
                elif c == 'C': opts['check_config'] = True
                elif c == 'V': opts['version'] = True
                elif c == 'h': opts['help'] = True
                elif c == 'H': opts['internal_help'] = True
                else:
                    raise CLIError("invalid command-line arguments", f"The following argument was not expected: -{c}", code=109)
                j += 1
            i += 1
        elif arg.startswith('-'):
            raise CLIError("invalid command-line arguments", f"The following argument was not expected: {arg}", code=109)
        else:
            opts['files'].append(arg)
            i += 1

    return opts
