{"command":"cat << 'EOF' > src/sql_engine.py
import sqlite3
import sys
import os
import json
import csv
import re
from datetime import datetime

class SQLEngine:
    def __init__(self):
        self.conn = sqlite3.connect(":memory:")
        self.cursor = self.conn.cursor()
        self.setup_tables()
        self.last_query_result = None
        self.last_description = None
        self.export_mode = None  # None, 'csv', 'json', 'jsonlines'
        self.export_target = None
        self.filter_in_pats = []
        self.filter_out_pats = []

    def setup_tables(self):
        # Create environ table
        self.cursor.execute("CREATE TABLE environ (name TEXT, value TEXT)")
        for k, v in os.environ.items():
            self.cursor.execute("INSERT INTO environ VALUES (?, ?)", (k, v))

        # Create logline table
        self.cursor.execute("""
            CREATE TABLE logline (
                log_line INTEGER PRIMARY KEY,
                log_time DATETIME,
                log_level TEXT,
                log_part TEXT,
                log_idle_msecs INTEGER,
                log_mark BOOLEAN DEFAULT 0,
                log_comment TEXT,
                log_tags TEXT,
                log_annotations TEXT,
                log_filters TEXT,
                log_path TEXT,
                log_body TEXT,
                log_raw TEXT
            )
        """)

        # Create syslog_log view
        self.cursor.execute("CREATE VIEW syslog_log AS SELECT * FROM logline")
        self.cursor.execute("CREATE VIEW generic_log AS SELECT * FROM logline")
        self.conn.commit()

    def populate_logs(self, parsed_entries):
        # parsed_entries: list of dicts with log_line, log_time, log_level, log_path, log_body, log_raw, etc.
        prev_dt = None
        for i, entry in enumerate(parsed_entries):
            dt = entry.get('dt')
            dt_str = dt.strftime("%Y-%m-%d %H:%M:%S.%f") if dt else None
            idle_msecs = 0
            if dt and prev_dt:
                idle_msecs = int((dt - prev_dt).total_seconds() * 1000)
            prev_dt = dt or prev_dt

            self.cursor.execute("""
                INSERT INTO logline (
                    log_line, log_time, log_level, log_part, log_idle_msecs,
                    log_mark, log_comment, log_tags, log_annotations, log_filters,
                    log_path, log_body, log_raw
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """, (
                i,
                dt_str,
                entry.get('level', 'info'),
                None,
                idle_msecs,
                0,
                None,
                None,
                None,
                None,
                entry.get('path'),
                entry.get('body', ''),
                entry.get('raw', '')
            ))
        self.conn.commit()

    def exec_command(self, cmd_str, quiet=False):
        cmd = cmd_str.strip()
        if not cmd:
            return

        if cmd.startswith(':'):
            # Colon command
            c = cmd[1:].strip()
            if c.startswith('echo'):
                msg = c[4:].strip()
                if not quiet:
                    sys.stdout.write(msg + "\n")
            elif c.startswith('filter-in'):
                pat = c[9:].strip()
                if pat:
                    self.filter_in_pats.append(re.compile(pat))
            elif c.startswith('filter-out'):
                pat = c[10:].strip()
                if pat:
                    self.filter_out_pats.append(re.compile(pat))
            elif c.startswith('write-csv-to'):
                target = c[12:].strip()
                self.export_csv(target)
            elif c.startswith('write-json-to'):
                target = c[13:].strip()
                self.export_json(target)
            elif c.startswith('write-jsonlines-to'):
                target = c[18:].strip()
                self.export_jsonlines(target)
            elif c.startswith('goto'):
                pass
            else:
                sys.stdout.write(f"  error: unknown command: “{c.split()[0]}”\n")

        elif cmd.startswith(';'):
            # SQL query
            sql = cmd[1:].strip()
            try:
                self.cursor.execute(sql)
                rows = self.cursor.fetchall()
                desc = self.cursor.description
                self.last_query_result = rows
                self.last_description = desc
                if not quiet and desc:
                    table_output = self.format_table(desc, rows)
                    sys.stdout.write(table_output)
            except Exception as e:
                sys.stdout.write(f"  error: failed to compile SQL statement\n reason: {str(e)}\n --> command-option:1\n | {sql}\n")

        elif cmd.startswith('|'):
            # Script file execution
            filepath = cmd[1:].strip()
            if not os.path.exists(filepath):
                sys.stdout.write(f"  error: unknown script -- {filepath} -- file not found\n --> command-option:1\n | |{filepath}\n")
            else:
                try:
                    with open(filepath, 'r') as f:
                        for line in f:
                            l = line.strip()
                            if l and not l.startswith('#'):
                                self.exec_command(l, quiet=quiet)
                except Exception as e:
                    sys.stdout.write(f"  error: failed to execute script {filepath}: {str(e)}\n")

    def export_csv(self, target):
        if not self.last_description or self.last_query_result is None:
            return
        cols = [d[0] for d in self.last_description]
        out_stream = sys.stdout if target == '-' else open(target, 'w', newline='')
        try:
