        for k, v in os.environ.items():
            self.cursor.execute("INSERT INTO environ VALUES (?, ?)", (k, v))

        # Create logline table
        self.cursor.execute("""
            CREATE TABLE logline (
                log_line INTEGER PRIMARY KEY,
                log_time DATETIME,
                log_level TEXT,
                log_part TEXT,
                log_idle_msecs INTEGER,
                log_mark BOOLEAN DEFAULT 0,
                log_comment TEXT,
                log_tags TEXT,
                log_annotations TEXT,
                log_filters TEXT,
                log_path TEXT,
                log_body TEXT,
                log_raw TEXT
            )
        """)

