        # parsed_entries: list of dicts with log_line, log_time, log_level, log_path, log_body, log_raw, etc.
        prev_dt = None
        for i, entry in enumerate(parsed_entries):
            dt = entry.get('dt')
            dt_str = dt.strftime("%Y-%m-%d %H:%M:%S.%f") if dt else None
            idle_msecs = 0
            if dt and prev_dt:
                idle_msecs = int((dt - prev_dt).total_seconds() * 1000)
            prev_dt = dt or prev_dt

            self.cursor.execute("""
                INSERT INTO logline (
                    log_line, log_time, log_level, log_part, log_idle_msecs,
                    log_mark, log_comment, log_tags, log_annotations, log_filters,
                    log_path, log_body, log_raw
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """, (
