import curses
import sys

def run_tui(log_entries):
    lines = [entry.get('raw', '') for entry in log_entries]
    if not lines:
        lines = ["No log messages loaded. Press 'q' to exit or '?' for help."]

    def main(stdscr):
        try:
            curses.curs_set(0)
        except Exception:
            pass
        stdscr.clear()
        height, width = stdscr.getmaxyx()

        offset = 0
        while True:
            stdscr.clear()
            height, width = stdscr.getmaxyx()
            if height < 2 or width < 2:
                break

            # Header
            header_text = " LNAV - Logfile Navigator ".center(width - 1, " ")
            try:
                stdscr.addstr(0, 0, header_text[:width-1], curses.A_REVERSE)
            except Exception:
                pass

            # Log content
            visible_lines = height - 2
            for i in range(visible_lines):
                idx = offset + i
                if idx < len(lines):
                    line_str = lines[idx][:width-1]
                    try:
                        stdscr.addstr(i + 1, 0, line_str)
                    except Exception:
                        pass

            # Footer
            footer_text = " q: Quit | ?: Help | j/k: Scroll ".center(width - 1, " ")
            try:
                stdscr.addstr(height - 1, 0, footer_text[:width-1], curses.A_REVERSE)
            except Exception:
                pass

            stdscr.refresh()
            try:
                ch = stdscr.getch()
            except Exception:
                break

            if ch in (ord('q'), ord('Q')):
                break
            elif ch in (curses.KEY_DOWN, ord('j')):
                if offset + visible_lines < len(lines):
                    offset += 1
            elif ch in (curses.KEY_UP, ord('k')):
                if offset > 0:
                    offset -= 1

    try:
        curses.wrapper(main)
    except Exception:
        pass
