            for row in self.last_query_result:
                obj = {col: val for col, val in zip(cols, row)}
                out_stream.write(json.dumps(obj) + "\n")
        finally:
            if target != '-':
                out_stream.close()

    def format_table(self, desc, rows):
        if not desc:
            return ""
        col_names = [d[0] for d in desc]
        if not rows:
            return " ".join(col_names) + " \n"

        col_is_num = []
        for col_idx in range(len(col_names)):
            is_num = True
            has_num = False
            for row in rows:
                val = row[col_idx]
                if val is not None:
                    if isinstance(val, (int, float)):
                        has_num = True
                    else:
                        is_num = False
                        break
            col_is_num.append(is_num and has_num)

        formatted_rows = []
        for row in rows:
            frow = []
            for val in row:
                if val is None:
                    frow.append("<NULL>")
                else:
                    frow.append(str(val))
            formatted_rows.append(frow)

        col_widths = []
        for col_idx, name in enumerate(col_names):
            max_w = len(name)
            for frow in formatted_rows:
                max_w = max(max_w, len(frow[col_idx]))
            if col_is_num[col_idx]:
                max_w = max(max_w, 4)
            col_widths.append(max_w)

        header_parts = []
        for col_idx, name in enumerate(col_names):
            w = col_widths[col_idx]
            if col_is_num[col_idx]:
                header_parts.append(name.rjust(w))
            else:
                header_parts.append(name.ljust(w))
        header_str = " ".join(header_parts) + " \n"

        row_strs = []
        for frow in formatted_rows:
            row_parts = []
            for col_idx, cell in enumerate(frow):
                w = col_widths[col_idx]
                if col_is_num[col_idx]:
                    row_parts.append(cell.rjust(w))
                else:
                    row_parts.append(cell.ljust(w))
            row_strs.append(" ".join(row_parts) + " ")

        return header_str + "\n".join(row_strs) + "\n"
EOF"}
